  // emer
  emerEventStatus() {
    return this.prisma.event_status.findMany({orderBy: {id: 'asc'}})
  }

  emerEventDocStatus() {
    return this.prisma.event_doc_status.findMany({
      orderBy: {id: 'asc'},
      where: {
        id: {
          in: [3, 4, 5, 6]
        }
      }
    })
  }

