  async doc41Action(id: any, payload: any, userId: any) {
    const {event_doc_status_id, doc_41_input_shipper_operation, doc_41_input_shipper_note} = payload

    const result = await this.prisma.$transaction(async (prisma) => {
      const newDate = getTodayNowAdd7()
      const todayStart = getYearStartAdd7().toDate()
      const todayEnd = getYearEndAdd7().toDate()

      const group = await this.prisma.group.findFirst({
        where: {
          account_manage: {
            some: {
              account_id: Number(userId)
            }
          }
        },
        select: {
          id: true,
          user_type: {
            select: {
              id: true
            }
          }
        }
      })
      const userTypeId = group.user_type?.id
      const groupId = group?.id

      if (userTypeId !== 3 && userTypeId !== 4) {
        throw new HttpException(
          {
            status: HttpStatus.BAD_REQUEST,
            error: 'Uset Type Is NOT MATCH'
          },
          HttpStatus.BAD_REQUEST
        )
      }

      const checkStatusRunId = await prisma.event_runnumber_emer.findFirst({
        where: {
          event_status_id: 2,
          event_document_emer: {
            some: {
              id: Number(id)
            }
          }
        },
        select: {
          id: true
        }
      })

      if (checkStatusRunId) {
        throw new HttpException(
          {
            status: HttpStatus.BAD_REQUEST,
            error: 'Status Closed Is NOT Action'
          },
          HttpStatus.BAD_REQUEST
        )
      }

      await prisma.event_document_emer.updateMany({
        where: {
          id: Number(id)
        },
        data: {
          doc_41_input_shipper_operation: doc_41_input_shipper_operation || null,
          doc_41_input_shipper_note: doc_41_input_shipper_note || null,
          event_doc_status_id: event_doc_status_id,
          update_date: getTodayNowAdd7().toDate(),
          update_date_num: getTodayNowAdd7().unix(),
          update_by: Number(userId)
        }
      })

      await prisma.event_document_emer_action.create({
        data: {
          event_document_emer: {
            connect: {
              id: Number(id)
            }
          },
          event_doc_status: {
            connect: {
              id: event_doc_status_id
            }
          },
          group: {
            connect: {
              id: groupId
            }
          },
          user_type: {
            connect: {
              id: userTypeId
            }
          },
          event_doc_master: {
            connect: {
              id: 4
            }
          },
          create_date: getTodayNowAdd7().toDate(),
          create_date_num: getTodayNowAdd7().unix(),
          create_by_account: {
            connect: {
              id: Number(userId)
            }
          }
        }
      })

      const eventRunId = await prisma.event_runnumber_emer.findFirst({
        where: {
          event_document_emer: {
            some: {
              id: Number(id)
            }
          }
        },
        select: {
          id: true
        }
      })

      return {
        eventRunId: Number(eventRunId?.id)
      }
    })
    const findOnce = await this.emerOnce(result?.eventRunId, userId)

    await this.prisma.event_document_emer_log_history.create({
      data: {
        temp: JSON.stringify(findOnce),
        group: {
          connect: {
            id: findOnce?.group_id
          }
        },
        user_type: {
          connect: {
            id: findOnce?.user_type_id
          }
        },
        event_document_emer: {
          connect: {
            id: Number(id)
          }
        },
        create_date: getTodayNowAdd7().toDate(),
        create_date_num: getTodayNowAdd7().unix(),
        create_by_account: {
          connect: {
            id: Number(userId)
          }
        }
      }
    })

    // เพิ่มคนสร้าง
    const docId = await this.prisma.event_document_emer.findFirst({
      where: {
        id: Number(id)
      },
      select: {
        id: true,
        create_by: true,
        group: true,
        group_id: true,
        doc_4_input_date_time_of_the_incident: true,
        event_runnumber_emer: {
          include: {
            event_doc_emer_type: true,
            event_doc_emer_gas_tranmiss: true
          }
        }
      }
    })
    const shipperCreate = await this.prisma.account.findFirst({
      where: {
        id: Number(docId?.create_by),
        account_manage: {
          some: {
            user_type_id: {
              in: [3,4]
            },
            account_role: {
              some: {
                role: {
                  menus_config: {
                    some: {
                      menus_id: 107,
                      // f_noti_inapp: 1
                      f_noti_email: 1
                    }
                  }
                }
              }
            }
          }
        }
      },
      select: {
        id: true,
        email: true,
        first_name: true,
        last_name: true,
        telephone: true,
        account_manage: {
          include: {
            account_role: {
              include: {
                role: true
              }
            }
          }
        }
      }
    })

    const shipperEmailArr = [docId?.group?.email || null, shipperCreate?.email || null]?.filter((f: any) => f !== null).join(', ')

    const header = event_doc_status_id === 5 ? `Shipper ${docId?.group?.name} รับทราบออกคำสั่งปรับปริมาณก๊าซจากเหตุการณ์ฉุกเฉิน/เหตุการณ์ความไม่สมดุลอย่างรุนแรง` : ``
    const subject = event_doc_status_id === 5 ? `Events/Emergency Difficult Day - Shipper Acknowledge (Doc.4)` : ``

    const excelBuffer = await this.doc41PDF(docId?.id, null, null, docId?.group_id, true)
    try {
      const emailNotificationData = await emailNotificationDAM(this.prisma, 36) // emailNotificationData?.subject subject: emailNotificationData?.subject || "", detail: emailNotificationData?.detail || "",
      const tsoMail = await emailGetpermissionEmailTSO(this.prisma, 106) // menus_id event 105 | (doc 1 2 3) Off-spec Gas 107 | (doc 3.9 4 5 6) Emergency/Difficult Day 106 | (doc 7 8) OFO 1013

      const originalData = {
        cc: null,
        header: header,
        // sendEmail: shipperEmailArr,
        sendEmail: tsoMail,
        subject: emailNotificationData?.subject || '',
        detail: emailNotificationData?.detail || '',
        excelBuffer: excelBuffer,
        tagHTMLDetail: `
        <div>
          <ul>
            <li>Event Code: ${docId?.event_runnumber_emer?.event_nember || ''}</li>
            <li>Type :  ${docId?.event_runnumber_emer?.event_doc_emer_type?.name_en || ''}</li>
            <li>Date :  ${docId?.doc_4_input_date_time_of_the_incident || ''}</li>
            <li>ระบบส่งก๊าซ :  ${docId?.event_runnumber_emer?.event_doc_emer_gas_tranmiss_id === 5 ? docId?.event_runnumber_emer?.event_doc_emer_gas_tranmiss_other : docId?.event_runnumber_emer?.event_doc_emer_gas_tranmiss?.name || ''}</li>
          </ul>
        </div>
        `,
        filename: 'emergency_difficult_day_document.pdf',
        contentType: 'application/pdf'
      }
      await sendEmailProviderCustomDocs(originalData)
    } catch (error) {}

    return findOnce
  }

